                mixed = (mixed << 32) | (uint)attackerSlot;
                mixed ^= (ulong)(uint)value * 0x9e3779b185ebca87UL;
                mixed ^= mixed >> 30;
                mixed *= 0xbf58476d1ce4e5b9UL;
                mixed ^= mixed >> 27;
                mixed *= 0x94d049bb133111ebUL;
                mixed ^= mixed >> 31;
                return mixed;
            }
